        try {
            return (function(){
var ga=new GlideAggregate("sn_lg_ops_matter");
ga.addAggregate("COUNT");ga.query();
var c=ga.next()?parseInt(ga.getAggregate("COUNT")):0;
if(c>=50)return{status:"ready",actualValue:c+" matters",finding:c+" legal matters found."};
if(c>0)return{status:"needs_attention",actualValue:c+" matters",finding:c+" legal matters found."};
return{status:"value_blocker",actualValue:"0 matters",finding:"No legal matters found."};
