        try {
            return (function(){
var ga=new GlideAggregate("sn_lg_ops_document");
ga.addAggregate("COUNT");ga.query();
var c=ga.next()?parseInt(ga.getAggregate("COUNT")):0;
if(c>=50)return{status:"ready",actualValue:c+" documents",finding:c+" legal documents found."};
if(c>0)return{status:"needs_attention",actualValue:c+" documents",finding:c+" legal documents found."};
return{status:"needs_attention",actualValue:"0 documents",finding:"No legal documents found."};
})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0001215: ' + e.message };
        }
    },
    CHK0001216: function() {
        try {
            return (function(){
var ga=new GlideAggregate("sn_lg_ops_matter_team");
ga.addAggregate("COUNT");ga.query();
var c=ga.next()?parseInt(ga.getAggregate("COUNT")):0;
